entries[87738] = { ["name"] = "Bauplan: Fürst von Schmetternichs Todeszielfernrohr", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung von Fürst von Schmetternichs Todeszielfernrohr.\n\nFürst von Schmetternichs Todeszielfernrohr\nBenötigt Stufe 85\nBenutzen: Bringt Fürst von Schmetternichs Todeszielfernrohr dauerhaft an einer Fernkampfwaffe an, sodass manchmal Eure Beweglichkeit 10 Sek. lang um 1800 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Geistereisenbolzen (18), Rubellit (2), Geist der Harmonie" }
entries[87739] = { ["name"] = "Bauplan: Verspiegeltes Zielfernrohr", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines verspiegelten Zielfernrohrs.\n\nVerspiegeltes Zielfernrohr\nBenötigt Stufe 85\nBenutzen: Bringt ein verspiegeltes Zielfernrohr dauerhaft an einer Fernkampfwaffe an, sodass manchmal Euer kritischer Trefferwert 10 Sek. lang um 900 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden.\nVerkaufspreis:\nBenötigt Geistereisenbolzen (4), Lapislazuli (2)" }
entries[87740] = { ["name"] = "Bauplan: Leichte Retinarüstung", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung einer leichten Retinarüstung.\n\nLeichte Retinarüstung\nWird beim Aufheben gebunden\nKopf Stoff\n1733 Rüstung\n+1.522 Ausdauer\n+855 Intelligenz\n\nMetasockel\nZahnradsockel\nZahnradsockel\nSockelbonus: + 180 Intelligenz\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 87\nBenötigt Ingenieurskunst (600)\nVerkaufspreis:\nBenötigt Lebendiger Stahl (6), Chrysokoll , Geistereisenbolzen (6)" }
