entries[87746] = { ["name"] = "Bauplan: Verstärkte Retinarüstung", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung einer verstärkten Retinarüstung.\n\nVerstärkte Retinarüstung\nWird beim Aufheben gebunden\nKopf Platte\n4191 Rüstung\n+855 Stärke\n+1.522 Ausdauer\n\nMetasockel\nZahnradsockel\nZahnradsockel\nSockelbonus: + 180 Stärke\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 87\nBenötigt Ingenieurskunst (600)\nVerkaufspreis:\nBenötigt Lebendiger Stahl (6), Geistereisenbolzen (12)" }
entries[87747] = { ["name"] = "Bauplan: Pulverfass des Schlossermeisters", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines Pulverfasses des Schlossermeisters.\n\nPulverfass des Schlossermeisters\nBenötigt Ingenieurskunst (525)\nBenutzen: Sprengt verschlossene Türen und Kisten auf, die eine Fertigkeit von bis zu 450 im Schlossknacken benötigen.\nVerkaufspreis:\nBenötigt Einfaches Holz , Hochexplosives Schwarzpulver" }
entries[87748] = { ["name"] = "Bauplan: Wassergleitjets", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung von Wassergleitjets.\nBringt an einem Gürtel dauerhaft Wassergleitjets an, die es Euch gestatten, auf dem Wasser zu wandeln, und die Euer Schwimmtempo bis zu 12 Sek. lang erhöhen.\n\nDie Jets können nur einmal alle 30 Sek. eingesetzt werden und benötigen eine Ingenieursfertigkeit von mindestens 500." }
entries[87750] = { ["name"] = "Bauplan: G91-Landhai", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines G91-Landhais.\n\nG91-Landhai\nBenötigt Stufe 85\nBenutzen: Fügt einem Gegner in bis zu 45 Metern Entfernung und Gegnern innerhalb von 10 Metern um das Hauptziel 37500 Feuerschaden zu. (1 Min Abklingzeit)\nBenötigt Geistereisenbolzen (2), Hochexplosives Schwarzpulver (2)" }
entries[87751] = { ["name"] = "Bauplan: Goblinflammenwerfer - Nr. II", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines Goblinflammenwerfers - Nr. II.\n\nGoblindrachengewehr - Nr. II\nBenötigt Stufe 85\nBenutzen: Entfesselt eine Blitzentladung, die Zielen in einem 10 Meter großen kegelförmigen Bereich vor dem Wirkenden 4 Sek. lang alle 0.5 Sek. 4500 Naturschaden zufügt.\n\nKann während der Bewegung gewirkt werden. (30 Sek. Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Geistereisenbolzen (3), Hochexplosives Schwarzpulver (8)" }
entries[87752] = { ["name"] = "Bauplan: Blingtron 4000", ["text"] = "Benötigt Ingenieurskunst (600)\nBenutzen: Lehrt Euch die Herstellung eines Blingtron 4000.\n\nBlingtron 4000\nWird beim Aufheben gebunden\nSpielzeug\nBenötigt Ingenieurskunst (600)\nBenutzen: Setzt den unglaublichen Blingtron 4000 zusammen, einen Roboter von unendlichem Reichtum. Bling, wie er gerne genannt wird, händigt jedem, der mit ihm spricht, ein zufälliges Geschenk aus, aber nur ein Mal pro Tag. Hält 10 Min. lang an. (4 Std. Abklingzeit)\nBenötigt Lebendiger Stahl (4), Trilliumbarren (4), Geistereisenbarren (4), Aragonit (4), Dioptas (4), Geist der Harmonie (4)" }
entries[87753] = { ["name"] = "Bauplan: Nebeldurchdringende Brille", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung einer nebeldurchdringenden Brille.\n\nNebeldurchdringende Brille\nWird beim Anlegen gebunden\nKopf\nAnlegen: Ermöglicht Euch, zusätzliche Erzadern und Kräutervorkommen aufzuspüren, während Ihr Euch in Pandaria befindet.\n\"Obwohl diese Brille sehr modisch ist, muss sie nicht aufgesetzt werden, um von ihrer Spezialfähigkeit zu profitieren.\"\nVerkaufspreis:\nBenötigt Geistereisenbolzen (8), Geist der Harmonie (2)" }
entries[87754] = { ["name"] = "Bauplan: Thermischer Amboss", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines thermischen Ambosses.\n\nThermischer Amboss\nBenutzen: Platziert einen thermischen Amboss zu Euren Füßen, der allen in der Nähe befindlichen Charakteren erlaubt, sowohl einen Amboss als auch eine Schmiede zu benutzen. Hält 5 Min. lang an. (5 Min Abklingzeit)\n20 Aufladungen\nBenötigt Hochexplosives Schwarzpulver (8), Geistereisenbolzen (6)" }
entries[87755] = { ["name"] = "Bauplan: Wurmlochgenerator: Pandaria", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines Wurmlochgenerator: Pandaria.\n\nWurmlochgenerator: Pandaria\nWird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst (500)\nBenutzen: Teleportiert Euch an irgendeinen Ort in Pandaria. Der exakte Ort ist schwer zu bestimmen, aber er ist wahrscheinlich ziemlich weit entfernt... (15 Min Abklingzeit)\n\"An der Seite ist eine winzige Notiz: Huiiiiiiiiiiiiiii!\"\nVerkaufspreis:\nBenötigt Trilliumbarren (12), Geist der Harmonie (2)" }
entries[87756] = { ["name"] = "Bauplan: Dampfgefüllter Ballon", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines dampfgefüllten Ballons." }
entries[87757] = { ["name"] = "Bauplan: Geistereisendrachling", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines Geistereisendrachlings.\n\nGeistereisendrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nZahnradsockel\nZahnradsockel\nZahnradsockel\n\nBenötigt Stufe 87\nAnlegen: Eure Angriffe haben eine Chance, einen Geistereisendrachling zu beschwören, der 20 Sek. lang an Eurer Seite kämpft. (Procchance: 25%, 1Min. Abklingzeit)\nVerkaufspreis:\nBenötigt Windwollstoff (12), Geistereisenbolzen (8), Hochexplosives Schwarzpulver (4)" }
entries[87758] = { ["name"] = "Bauplan: Mechanischer Pandarendrachling", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines mechanischen Pandarendrachlings.\n\nMechanischer Pandarendrachling\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Welpling beschwören oder wieder freigeben.\nVerkaufspreis:\nBenötigt Geistereisenbarren (4), Trilliumbarren (6), Geist der Harmonie (2)" }
entries[87759] = { ["name"] = "Bauplan: Großwildjäger", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines Großwildjägers.\n\nGroßwildjäger\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n3,354 - 6,229 Schaden Tempo 2.80\n(1,711 Schaden pro Sekunde)\n+449 Beweglichkeit\n+703 Ausdauer\nErhöht Eure kritische Trefferwertung um + 321.\nErhöht Eure Tempowertung um + 283.\n\nRoter Sockel\nSockelbonus: + 10 Beweglichkeit\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 85\nVerkaufspreis:\nBenötigt Geistereisenbolzen (12), Haarfeiner Sprengstoffauslöser , Schäftung aus Walnussholz , Verspiegeltes Zielfernrohr" }
entries[87760] = { ["name"] = "Bauplan: Trilliumlangstreckenpräzisionsgewehr", ["text"] = "Benötigt Ingenieurskunst (525)\nBenutzen: Lehrt Euch die Herstellung eines Trilliumlangstreckenpräzisionsgewehrs.\n\nTrilliumlangstreckenpräzisionsgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n5,704 - 10,595 Schaden Tempo 2.80\n(2,911 Schaden pro Sekunde)\n+717 Beweglichkeit\n+1.195 Ausdauer\nErhöht Eure Trefferwertung um + 435.\nErhöht Eure Waffenkundewertung um + 546.\n\nGelber Sockel\nSockelbonus: + 10 Beweglichkeit\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 90\nVerkaufspreis:\nBenötigt Trilliumbarren (12), Haarfeiner Sprengstoffauslöser , Geist der Harmonie , Fürst von Schmetternichs Todeszielfernrohr" }
entries[87761] = { ["name"] = "Bauplan: Rakete mit abgereichertem Kyparium", ["text"] = "Benötigt Ingenieurskunst (600)\nBenutzen: Lehrt Euch die Herstellung einer Rakete mit abgereichertem Kyparium\n\nRakete mit abgereichertem Kyparium\nEinzigartig\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Höhepunkt goblinischer Ingenieurskunst! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBenötigt Lebendiger Stahl (12), Kyparit (200), Kugel der Geheimnisse (3), Hochexplosives Schwarzpulver (12), Geist der Harmonie (12), Geistereisenbolzen (20)" }
entries[87762] = { ["name"] = "Bauplan: Geosynchroner Weltendreher", ["text"] = "Benötigt Ingenieurskunst (600)\nBenötigt Gnomeningenieur\nBenutzen: Lehrt Euch die Herstellung eines geosynchronen Weltendrehers.\n\nGeosynchroner Weltendreher\nEinzigartig\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Apparatur, die die Welt selbst unter Euch rotieren lässt! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBenötigt Lebendiger Stahl (12), Trilliumbarren (12), Geist der Harmonie (12), Geistereisenbolzen (20), Kugel der Geheimnisse (3)" }
entries[87763] = { ["name"] = "Ellas Bräu", ["text"] = "Questgegenstand\nBenutzen: Gewährt eine Kostprobe von Ellas Bräu. (30 Sek. Abklingzeit)\n\"Ein Schwarzbier mit wohlriechendem Aroma. Abzuliefern bei Chen Sturmbräu.\"" }
entries[87764] = { ["name"] = "Schlangenherzfeuerwerk", ["text"] = "Benutzen: Schießt ein Feuerwerk in die Luft, das in der Form der Jadeschlange explodiert.\nVerkaufspreis:" }
entries[87768] = { ["name"] = "Zügel der Onyxwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange.\nBeschwört eine reitbare Onyxwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange." }
