entries[87811] = { ["name"] = "Auftragsgemälde", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\n\"Ein atemberaubendes Gemälde, angefertigt im Auftrag des Tempels der Jadeschlange.\"" }
entries[87812] = { ["name"] = "Empfehlungsschreiben der Jadeschlange", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Empfehlungsschreiben vom Tempel der Jadeschlange für ein großartiges Kunstwerk.\"" }
entries[87813] = { ["name"] = "Fesseln der Zan'thik", ["text"] = "Questgegenstand\n\"Schwere Metallschellen und Ketten, versehen mit summenden Bernkristallen.\"" }
entries[87814] = { ["name"] = "Gravierte Jadescheibe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 90\n\"Ein wunderschönes Gedicht, das von einem hochtalentierten Schreiber in Jade graviert wurde.\"" }
