entries[87829] = { ["name"] = "Rezept: Fleischfarbene Tinte", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Inschriftenkunde (600)\nBenutzen: Lehrt Euch die Herstellung fleischfarbener Tinte.\nVerkaufspreis:\nFleischfarbene Tinte\nWird beim Aufheben gebunden\nBenötigt Stufe 90\n\"Eine seltene Kalligrafietinte. Sie verfügt nicht über magische Eigenschaften, aber ihre Färbung ist bei Schreibern zur Verwendung in Kriegserzählungen heiß begehrt.\"\nBenötigt Tigerblutpigmente (2), Geist der Harmonie , Sternenlichttinte" }
entries[87830] = { ["name"] = "Rezept: Tigerbluttinktur", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Inschriftenkunde (600)\nBenutzen: Lehrt Euch die Herstellung von Tigerbluttinktur.\nVerkaufspreis:\nTigerbluttinktur\nWird beim Aufheben gebunden\nBenötigt Stufe 90\nBenutzen:\n3 Aufladungen\n\"Der perfekte Farbton um Gewalt und Tod hervorzurufen. Es bedaf jedoch viel Arbeit, sie in eine brauchbare Tinte zu verwandeln.\"\nBenötigt Tigerblutpigmente (10)" }
