entries[87841] = { ["name"] = "Korvens experimentelle Granaten", ["text"] = "Questgegenstand\nBenutzen: Wirft die Phiole und entzündet die Kyparitrüstung von Zielen im Umkreis von 10 Metern um das Ziel.\n\"Phiolen mit 2 Kammern die reaktive Flüssigkeiten enthalten. Ganz vorsichtig.\"" }
entries[87871] = { ["name"] = "Massiver Kyparitkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Überraschend leicht.\"" }
