entries[87874] = { ["name"] = "Kyparitsplitter", ["text"] = "Questgegenstand\n\"Brocken organischen Kyparits, verkrustet durch Salz und Matsch.\"" }
entries[87875] = { ["name"] = "Glyphe 'Lichtquell'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Lichtbrunnen heilt nicht mehr automatisch Ziele in der Nähe, kann aber von Spielern angeklickt werden, woraufhin er 50% mehr heilt als normalerweise.\nVerkaufspreis:" }
entries[87878] = { ["name"] = "Enorme Kunchongmandibeln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die mächtigen Kiefer von Karanosh haben zahllose Mushan zu Futter für ihre Jungen verarbeitet.\"" }
entries[87880] = { ["name"] = "Glyphe 'Schlüpfriges Gebräu'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr mit Eurer Fähigkeit 'Schlüpfriges Gebräu' einen Effekt entfernt, werdet Ihr um 10% Eurer maximalen Gesundheit geheilt.\nVerkaufspreis:" }
entries[87881] = { ["name"] = "Glyphe 'Knisternder Tigerblitz'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eures Zaubers 'Knisternder Jadeblitz' hat nun die Farbe des Weißen Tigers.\nVerkaufspreis:" }
entries[87882] = { ["name"] = "Glyphe 'Fliegender Schlangentritt'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Fliegender Schlangentritt' endet automatisch, wenn Ihr einen Gegner trefft, wodurch der Flächenschadenseffekt und die Verlangsamung ausgelöst werden.\nVerkaufspreis:" }
entries[87883] = { ["name"] = "Glyphe 'Ehre'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr verbeugt Euch nach jedem erfolgreichen Einsatz von 'Berührung des Todes'.\nVerkaufspreis:" }
entries[87884] = { ["name"] = "Glyphe 'Hieb'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr greift immer mit Händen und Füßen an, wenn Ihr 'Hieb' einsetzt, selbst wenn Ihr keine Faustwaffen angelegt habt.\nVerkaufspreis:" }
entries[87885] = { ["name"] = "Glyphe 'Springender Tigertritt'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eurer Fähigkeit 'Tritt der aufgehenden Sonne' hat nun die Farbe des Weißen Tigers.\nVerkaufspreis:" }
entries[87887] = { ["name"] = "Glyphe 'Geisterrolle'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt 'Rollen' und 'Chitorpedo' einsetzen, während Ihr Euch tot in Geistergestalt bewegt.\nVerkaufspreis:" }
entries[87888] = { ["name"] = "Glyphe 'Kampfstellung'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Geist erscheint nun in Kampfstellung, wenn Ihr 'Transzendenz' einsetzt.\nVerkaufspreis:" }
entries[87889] = { ["name"] = "Glyphe 'Wasserrolle'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt 'Rollen' oder 'Chitorpedo' einsetzen, um Euch über Wasser fortzubewegen.\nVerkaufspreis:" }
entries[87890] = { ["name"] = "Glyphe 'Zenflug'", ["text"] = "Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Zenflug'. 'Zenflug' setzt voraus, dass Ihr eine Fluglizenz besitzt.\n\nZenflug\nIhr fliegt auf einer meditativen Wolke mit hoher Geschwindigkeit durch die Luft.\nVerkaufspreis:" }
entries[87891] = { ["name"] = "Glyphe 'Leben nach dem Tode'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Chance, eine heilende Sphäre zu erzeugen, wenn Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, um 100%.\nVerkaufspreis:" }
entries[87892] = { ["name"] = "Glyphe 'Furorfäuste'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr 'Furorfäuste' kanalisiert, ist Eure Parierchance um 100% erhöht.\nVerkaufspreis:" }
entries[87893] = { ["name"] = "Glyphe 'Stärkendes Gebräu'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Stärkendes Gebräu' verringert Euren erlittenen Schaden um zusätzlich 5%, erhöht Eure Gesundheit dafür aber um 10% statt um 20%.\nVerkaufspreis:" }
entries[87894] = { ["name"] = "Glyphe 'Stieren des Ochsen'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Stieren des Ochsen'.\n\nStieren des Ochsen\nEure Statue des Schwarzen Ochsen zieht den Hass des Ziels auf sich, verringert dessen Bewegungstempo um 50% und zwingt es, die Statue des Schwarzen Ochsen 8 Sek. lang anzugreifen. Die Statue muss sich innerhalb von 40 Metern vom Ziel befinden.\n\nSetzt voraus, dass Eure Statue des Schwarzen Ochsen aktiv ist.\nVerkaufspreis:" }
entries[87895] = { ["name"] = "Glyphe 'Lebenskokon'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Lebenskokon' kann nun auch gewirkt werden, wenn Ihr betäubt seid.\nVerkaufspreis:" }
entries[87896] = { ["name"] = "Glyphe 'Glück im Unglück'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Eure Gesundheit unter 25% fällt, wird automatisch eine kostenlose heilende Sphäre neben Euch erzeugt. Dieser Effekt kann nur ein Mal alle 30 Sek. auftreten. (30s Abklingzeit)\nVerkaufspreis:" }
entries[87897] = { ["name"] = "Glyphe 'Paralyse'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Paralyse' entfernt nun zusätzlich sämtliche regelmäßigen Schadenseffekte vom Ziel.\nVerkaufspreis:" }
entries[87898] = { ["name"] = "Glyphe 'Sparring'", ["text"] = "Klassen: Mönch\nBenötigt Stufe 25\nBenutzen:\nVerkaufspreis:" }
entries[87899] = { ["name"] = "Glyphe 'Entgiftung'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn 'Entgiftung' erfolgreich einen schädlichen Effekt entfernt, wird Euer Ziel zusätzlich um 5% geheilt.\nVerkaufspreis:" }
entries[87900] = { ["name"] = "Glyphe 'Karmaberührung'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Karmaberührung' hat nun eine Reichweite von 25 Metern.\nVerkaufspreis:" }
entries[87901] = { ["name"] = "Glyphe 'Schadensumlenkung'", ["text"] = "Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n[ Nebelwirker : Außerhalb von Arenen und Schlachtfeldern:\nEuer Zauber 'Erbauung' kostet 10% Mana anstelle des Chi.\n\nInnerhalb von Arenen und Schlachtfeldern: ]Eure Fähigkeit 'Schadensumleitung' kann jetzt auf andere Verbündete angewandt werden, allerdings ist in diesem Fall die Heilung um 50% verringert.\nVerkaufspreis:" }
entries[87902] = { ["name"] = "Glyphe 'Lichtbrunnen'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Lichtbrunnen heilt nicht mehr automatisch Ziele in der Nähe, kann aber von Spielern angeklickt werden, woraufhin er 50% mehr heilt als normalerweise.\nVerkaufspreis:" }
