entries[88360] = { ["name"] = "Preis des Fortschritts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+12 Intelligenz\nBenötigt Stufe 39\nAnlegen: Eure Heilzauber haben eine Chance, 95 Mana wiederherzustellen. (10% Chance, 55 Sek. Abklingzeit) (Procchance: 10%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[88361] = { ["name"] = "Handschuhe der explodierenden Schmerzen", ["text"] = "Wird beim Aufheben gebunden\nHände Kette\n190 Rüstung\n+14 Ausdauer\n+9 Intelligenz\n+6 Willenskraft\nErhöht Eure Tempowertung um + 6.\nHaltbarkeit 50 / 50\nBenötigt Stufe 39\nVerkaufspreis:" }
entries[88362] = { ["name"] = "Schulterschützer der schmerzhaften Lektionen", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n342 Rüstung\n+14 Ausdauer\n+9 Intelligenz\n+6 Willenskraft\nErhöht Eure kritische Trefferwertung um + 6.\nHaltbarkeit 85 / 85\nBenötigt Stufe 39\nVerkaufspreis:" }
entries[88368] = { ["name"] = "Fass mit Flammenbräus Sommerbier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 406.\nBenutzen: Beschwört 1 Min. lang ein Fass mit Flammenbräus Sommerbier am Zielort. Verbündete können das Fass benutzen, um um 2757 geheilt zu werden. 20 Aufladungen. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[88369] = { ["name"] = "Bierwuts Reservefass", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 406.\nBenutzen: Beschwört ein flammendes Fass aus Bierwuts eisener Reserve am Zielort, fügt allen in der Nähe befindlichen Gegnern 6 Sek. lang alle 0.5 Sek. 2201 Schaden zu. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[88370] = { ["name"] = "Plumpes Murmeltier", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört ein plumpes Murmeltier am Zielort. (10 Min Abklingzeit)" }
entries[88371] = { ["name"] = "Wassermelonenbombe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+700 Ausdauer\nAnlegen: Eure offensiven Angriffe und Fähigkeiten haben eine Chance, Euch 20 Sek. lang 1258 kritischen Trefferwert zu gewähren. (Procchance: 20%, 50s Abklingzeit)\nBenutzen: Wirft eine Wassermelone auf den Zielort, deren Aufprall alle Gegner in der Nähe mit klebrigem Fruchtfleisch bespritzt, was sie 3 Sek. lang bewegungsunfähig macht. Spielercharaktere sind davon nicht betroffen. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[88375] = { ["name"] = "Rübensandsack", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört 5 Min. lang einen Rübensandsack am Zielort, der als Zielattrappe dient.\n\nKann nur im Freien von Pandaria eingesetzt werden. (1 Stunde Abklingzeit)\n\"Eine Rübe mit extrem robustem Äußeren. Sie kann genauso gut Schläge einstecken wie ein Boss in heroischen Dungeons.\"" }
entries[88376] = { ["name"] = "Orange angemalte Rübe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 467.\nAnlegen: Eure offensiven Angriffe und Fähigkeiten haben eine Chance, Euch 20 Sek. lang 1258 Meisterschaft zu gewähren. (Procchance: 20%, 50s Abklingzeit)\nBenutzen: Wirft eine orange angemalte Rübe auf den Zielort, worauf alle Shed-Ling in der Nähe 3 Sek. lang vor Furcht flüchten. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[88377] = { ["name"] = "Rübenfarbsprühpistole", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schleudert eine Kugel oranger Farbe auf Euer aktuelles verbündetes Ziel, wodurch es 6 Sek. lang orange angemalt wird. (5 Min Abklingzeit)" }
entries[88378] = { ["name"] = "Mottallus' Spinndrüsen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 467.\nAnlegen: Eure offensiven Angriffe und Fähigkeiten haben eine Chance, Euch 20 Sek. lang 1258 Tempo zu gewähren. (Procchance: 20%, 50s Abklingzeit)\nBenutzen: Feuert ein Netz auf das Ziel und macht es 3 Sek. lang bewegungsunfähig. Hat keinen Effekt auf Spieler. Kann nur im Tal der Vier Winde und in der Krasarangwildnis verwendet werden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[88379] = { ["name"] = "Grummelkuchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 10 Sek. 200000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet einen zufälligen Stärkungszauber, der am Kun-Lai-Gipfel wirkt\n\nFunktioniert nur am Kun-Lai-Gipfel." }
entries[88380] = { ["name"] = "Schneelilienräucherwerk", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört 20 Sek. lang einen brennenden Stab aus Schneelilienräucherwerk am Zielort. (20 Min Abklingzeit)" }
entries[88381] = { ["name"] = "Silbersalbeiräucherwerk", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört 20 Sek. lang einen brennenden Stab aus Silbersalbeiräucherwerk am Zielort. (20 Min Abklingzeit)" }
entries[88382] = { ["name"] = "Kühnbohn Kafa", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 85\nBenutzen: Erhöht Euer Tempo 25 Sek. lang um 4000 und schärft Eure Sinne. Funktioniert nur am Kun-Lai-Gipfel. (10 Min Abklingzeit)" }
entries[88384] = { ["name"] = "Ritualjutetasche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt dem Anwendenden den Jutesegen, wodurch die Willenskraft 15 Min. lang um 5% erhöht wird, solange Ihr Euch am Kun-Lai-Gipfel aufhaltet. (10 Min Abklingzeit)" }
entries[88385] = { ["name"] = "Ho-zen-Götze", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Fokussiert Euren Blick stark auf das Tier und lässt es nach einigen Sekunden durch den Druck explodieren. (10 Min Abklingzeit)" }
entries[88386] = { ["name"] = "Tretbares Fass", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört ein Fass, das ihr durch die Gegend treten könnt. Vorsicht, der Inhalt könnte empfindlich sein. (10 Min Abklingzeit)" }
entries[88387] = { ["name"] = "Shushens Spucknapf", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört 1 Min. lang Shushens Spucknapf am Zielort. Verbündete können ihn anklicken, um ihn zu benutzen. (10 Min Abklingzeit)" }
entries[88388] = { ["name"] = "Ekliger Gaumenschmaus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 10) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 275 erhöht.\n\nIrgendetwas scheint allerdings nicht zu stimmen..." }
entries[88397] = { ["name"] = "Grummelbündel", ["text"] = "Wird beim Aufheben gebunden\n24 Platz Behälter\nVerkaufspreis:" }
entries[88398] = { ["name"] = "Wurzelgemüseeintopf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[88416] = { ["name"] = "Adrenalinspritze", ["text"] = "Benötigt Stufe 85\nBenutzen: Stellt 120000 Gesundheit wieder her. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[88417] = { ["name"] = "Gokk'loks Muschel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Steht auf einem Stück von Gokk'loks Muschel. Bewegung bricht den Effekt ab. (30 Min Abklingzeit)" }
entries[88487] = { ["name"] = "Flüchtige Kugel", ["text"] = "Benutzen: Wirft die flüchtige Kugel einem verbündeten Spieler zu. Falls er Platz in seinem Rucksack hat, wird er ihn fangen! Seid aber vorsichtig, sie ist flüchtig, es könnte alles Mögliche passieren!\nVerkaufspreis:" }
entries[88489] = { ["name"] = "Jadeschlangenfeuerwerk", ["text"] = "Benutzen: Schießt ein Feuerwerk in die Luft, das in der Form der Jadeschlange explodiert.\nVerkaufspreis:" }
