entries[88535] = { ["name"] = "Geschärfter Tuskarrspeer", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand\n14 - 27 Schaden Tempo 2.50\n(8.20 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nBenötigt Die Angler\n- Respektvoll\nBenutzen: Pflanzt den Speer in den Boden, woraufhin sich Eure Angelfertigkeit und die aller Angler innerhalb von 15 Metern um 15 erhöht. Hält 2 Min. lang an. (5 Min Abklingzeit)\n\"Ein traditioneller Tuskarrangelspeer - die Handwerkskunst ist eine Augenweide.\"" }
entries[88538] = { ["name"] = "Sha-besessener Kristall", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Tintiger Rauch wirbelt durch das Innere.\"" }
entries[88563] = { ["name"] = "Nats Anglertagebuch", ["text"] = "Accountgebunden\nDieser Gegenstand startet eine Quest.\nBenötigt Angeln (1)\n\"Durch das Lesen dieses Buches wird Eure Angelfertigkeit permanent um 50 erhöht, bis zu einem Maximum von 600.\"" }
