entries[89112] = { ["name"] = "Harmoniepartikel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wandelt zehn Harmoniepartikel zu einem Geist der Harmonie um." }
entries[89113] = { ["name"] = "Goldener Honig", ["text"] = "Questgegenstand\nBenutzen: Platziert den Honig in die Nähe des großen Nests im Arboretum, um den Obstgartennadler aus seinem Versteck zu locken. (3 Sek. Abklingzeit)" }
entries[89123] = { ["name"] = "Wukaosprengstoff", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert Wukaosprengstoff in der Nähe einer Kanone der Shao-Tien auf der Goldenen Treppe. (6 Sek. Abklingzeit)" }
entries[89124] = { ["name"] = "Himmlische Darbietung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Die Himmlischen Erhabenen\n- Wohlwollend\n\"Unter der Aufsicht der Himmlischen gewähren sie Euch ihren Segen, wenn Ihr in der Nähe ihrer Tempel seid.\"\nVerkaufspreis:" }
entries[89125] = { ["name"] = "Beutel mit Haustierbedarf", ["text"] = "Wird beim Aufheben gebunden" }
entries[89139] = { ["name"] = "Haustierkette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Eine Kette.\nVerkaufspreis:" }
entries[89154] = { ["name"] = "Zügel des purpurroten Pandarenphönix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren purpurroter Pandarenphönix und gibt ihn wieder frei. Das ist ein Flugreittier.\nVerkaufspreis:" }
entries[89155] = { ["name"] = "Onyxei", ["text"] = "Wird beim Aufheben gebunden\n\"Ein seltenes Ei von außergewöhnlichem Wert. Die Älteste Anli im Arboretum wäre sicherlich daran interessiert.\"" }
entries[89163] = { ["name"] = "Requirierter Raketenzünder", ["text"] = "Questgegenstand\nBenutzen: Feuert ein Bombardement aus Feuerwerkskörpern auf einen Starkarmgyrokopter.\n2 Aufladungen" }
