entries[89197] = { ["name"] = "Scherwindkaktussamen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Pflanzt einen Scherwindkaktussamen.\n\"Der Scherwindkaktus ist mit Millionen feinster Nadeln bedeckt, die den vorbeiziehenden Wind filtern. Windwollfasern und Reste anderer Materialien bleiben häufig an ihnen hängen.\"\nVerkaufspreis:" }
entries[89202] = { ["name"] = "Raptorblattsamen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Pflanzt Raptorblattsamen.\n\"Das Raptorblatt ist eine fleischfressende Pflanze, der regelmäßig Shed-Ling, Falken und andere Kleintiere zum Opfer fallen. Nach einem einzigen Fang stirbt sie, setzt dabei ihre Samen frei und lässt oft auch Überreste ihrer Beute zurück.\"\nVerkaufspreis:" }
entries[89205] = { ["name"] = "Minimanabombe", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Mit Rechtsklick diese Minimanabombe werfen. (3 Min Abklingzeit)" }
entries[89209] = { ["name"] = "Makelloses Kassenbuch eines Architekten", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter \"Restaurierte Artefakte\" protokolliert.\"" }
entries[89216] = { ["name"] = "Yis ungeliebter Helm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n4380 Rüstung\n+906 Stärke\n+1.719 Ausdauer\n+ 680 Ausweichen\nErhöht Eure Meisterschaftswertung um + 570.\n\nMetasockel\nBlauer Sockel\nSockelbonus: + 270 Ausdauer\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 90\nBenötigt Shado-Pan\n- Respektvoll\nVerkaufspreis:" }
entries[89222] = { ["name"] = "Wolkenring", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenötigt Orden der Wolkenschlange\n- Respektvoll\nBenutzen: Beschwört einen Wolkenring, durch den Euer Haustier springt. Benötigt ein fliegendes Haustier. (10 Min Abklingzeit)\n\"Unterhaltung für Euer fliegendes Haustier.\"\nVerkaufspreis:" }
entries[89223] = { ["name"] = "Rennflagge", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Orden der Wolkenschlange\n- Respektvoll\nBenutzen: Beschwört 15 Min. lang eine Rennflagge am Zielort. (30 Sek. Abklingzeit)\n\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:" }
entries[89224] = { ["name"] = "Schwebende Rennflagge", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Orden der Wolkenschlange\n- Respektvoll\nBenutzen: Beschwört 15 Min. lang eine schwebende Rennflagge an Eurem aktuellen Standort. Kann beim Reiten verwendet werden. (30 Sek. Abklingzeit)\n\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:" }
entries[89225] = { ["name"] = "Ziellinie", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Orden der Wolkenschlange\n- Respektvoll\nBenutzen: Beschwört 15 Min. lang eine Ziellinie am Zielort. (10 Min Abklingzeit)\n\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:" }
entries[89227] = { ["name"] = "Schwebende Ziellinie", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Orden der Wolkenschlange\n- Respektvoll\nBenutzen: Beschwört 15 Min. lang eine schwebende Ziellinie an Eurem aktuellen Standort. Kann beim Reiten verwendet werden. (10 Min Abklingzeit)\n\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:" }
entries[89230] = { ["name"] = "Erneuernder Bern", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Die Klaxxi\n- Wohlwollend\nBenutzen: Schließt Euch selbst in erneuernden Bern ein. Stellt im Verlauf von 10 Sek. 199999 Gesundheit und 300000 Mana wieder her.\nVerkaufspreis:" }
entries[89232] = { ["name"] = "Mogurune der Paralyse", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Meisterschaftswertung um + 809.\nBenötigt Stufe 90\nBenutzen: Platziert eine Mogurune der Paralyse auf dem Boden, die 1 Min. lang anhält und die nächste Kreatur 4 Sek. lang betäubt, die sie betritt. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[89233] = { ["name"] = "Klangglöckchensamen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Pflanzt Klangglöckchensamen.\n\"Die Harmonie der hellen und dunklen, glockenförmigen Blüten dieser Pflanze hat die pandarische Lied- und Dichtkunst über Jahrtausende hinweg beeinflusst.\"\nVerkaufspreis:" }
